import SpotifyWebApi from 'spotify-web-api-js';

const spotifyApi = new SpotifyWebApi();

export const getTokenFromUrl = () => {
  // Extract the access token from URL hash
  const hash = window.location.hash.substring(1);
  const params = new URLSearchParams(hash);
  return {
    access_token: params.get('access_token'),
  };
};

export const setAccessToken = (token) => {
  if (token) {
    localStorage.setItem('spotifyAccessToken', token); // Store token in localStorage
    spotifyApi.setAccessToken(token); // Set the token in the Spotify API helper
  }
};

export const getAccessToken = () => {
  // Get token from localStorage
  return localStorage.getItem('spotifyAccessToken');
};

export const validateToken = async () => {
  const token = getAccessToken();
  if (token) {
    spotifyApi.setAccessToken(token); // Set the token for validation
    try {
      await spotifyApi.getMe(); // Test if the token is valid
      return true;
    } catch (error) {
      console.error('Token validation failed:', error);
      return false;
    }
  }
  return false;
};

export const loginToSpotify = () => {
  const clientId = 'YOUR_CLIENT_ID';
  const redirectUri = 'http://localhost:3000'; // Change if needed
  const authEndpoint = 'https://accounts.spotify.com/authorize';
  const scopes = [
    'user-read-private',
    'user-read-email',
    'playlist-read-private',
    'playlist-read-collaborative',
  ];

  // Construct the Spotify auth URL
  const authUrl = `${authEndpoint}?client_id=${clientId}&redirect_uri=${encodeURIComponent(
    redirectUri
  )}&scope=${scopes.join('%20')}&response_type=token&show_dialog=true`;

  // Redirect to Spotify login
  window.location.href = authUrl;
};

export const checkAuthOnLoad = async () => {
  const token = getTokenFromUrl();
  if (token && token.access_token) {
    setAccessToken(token.access_token);
    window.location.hash = ''; // Clear the URL hash
  }

  const isValid = await validateToken();
  return isValid;
};
